use crate::{models::CompatibilityReport,provision,registry,runtime};
use std::{path::PathBuf,process::Command};
use tauri::AppHandle;
pub fn wp_cli(app:&AppHandle,site_id:&str,args:&[String],allow_unsafe:bool)->Result<String,String>{let site=registry::get_site(app,site_id)?;if !site.provisioned{return Err("WordPress is not installed.".into())}if args.is_empty(){return Err("WP-CLI arguments are empty.".into())}if !allow_unsafe&&["eval","eval-file","shell"].contains(&args[0].as_str()){return Err("This WP-CLI command requires Unsafe mode.".into())}provision::run_wp_version(app,&PathBuf::from(site.path).join("public"),args,&site.php_version)}
pub fn compatibility(app:&AppHandle,site_id:&str)->Result<CompatibilityReport,String>{let site=registry::get_site(app,site_id)?;let public=PathBuf::from(&site.path).join("public");let php=Command::new(runtime::php_exe_for(app,&site.php_version)?).arg("-c").arg(runtime::php_ini_for(app,&site.php_version)?).arg("-r").arg("echo PHP_VERSION;").output().map_err(|e|e.to_string())?;let php_version=String::from_utf8_lossy(&php.stdout).trim().to_string();let wp=provision::run_wp_version(app,&public,&vec!["core".into(),"version".into()],&site.php_version)?;let checksums=provision::run_wp_version(app,&public,&vec!["core".into(),"verify-checksums".into()],&site.php_version);let plugins=provision::run_wp_version(app,&public,&vec!["plugin".into(),"list".into(),"--format=count".into()],&site.php_version).unwrap_or_else(|_|"0".into()).trim().parse().unwrap_or(0);let themes=provision::run_wp_version(app,&public,&vec!["theme".into(),"list".into(),"--format=count".into()],&site.php_version).unwrap_or_else(|_|"0".into()).trim().parse().unwrap_or(0);let output=format!("PHP {php_version}\nWordPress {}\nCore checksums: {}\nPlugins: {plugins}\nThemes: {themes}",wp.trim(),if checksums.is_ok(){"PASS"}else{"FAIL"});Ok(CompatibilityReport{php_version,wordpress_version:wp.trim().into(),core_checksums_ok:checksums.is_ok(),plugin_count:plugins,theme_count:themes,output})}
